// BUILD EMAIL  (the code inside the "Build Email" node of the n8n workflow)
//
// The Flask backend sends two kinds of email. This code builds the subject, the HTML and the PDF
// attachments for both:
//   type "comparison" -> AI marks + admin marks + the PDF reports
//   type "result"     -> the student's own AI result (+ the AI report PDF)
//
// Layout of this file: 1 helpers, 2 colours, 3 feedback text -> HTML, 4 small HTML pieces,
//                      5 one email per item, 6 attach the PDFs.
// Email HTML uses plain tables and inline styles on purpose: Gmail and Outlook only support that.


// ── 1. Small helpers ────────────────────────────────────────────
// esc() makes text safe to put inside HTML.
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// num() turns a value into a number (or null). fmt() shows it tidily: 7.50 -> "7.5".
const num = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
const fmt = v => { const n = num(v); return n === null ? '-' : String(Math.round(n * 10) / 10); };


// ── 2. Colours and fonts (same as the web app) ──────────────────
const C = { ink: '#2B1B17', plum: '#5C3A41', peach: '#ECA087', peachInk: '#9A4A32', sand: '#F4F0EA', sunk: '#EAE3D9',
            line: '#DDD3C6', muted: '#766760', body: '#3A2B26', good: '#4A6B3A', mid: '#9A5B12', bad: '#A32A2A' };
const SANS = "'IBM Plex Sans','Segoe UI',Helvetica,Arial,sans-serif";
const MONO = "'IBM Plex Mono',Consolas,'Courier New',monospace";

// A score is green from 7, amber from 5, red below 5.
const scoreColor = v => { const n = num(v); return n === null ? C.muted : n >= 7 ? C.good : n >= 5 ? C.mid : C.bad; };
const scoreWord = v => { const n = num(v); return n === null ? '' : n >= 9 ? 'Excellent' : n >= 7 ? 'Good' : n >= 5 ? 'Average' : 'Needs work'; };
// How far apart the AI and the admin are (the difference is admin minus AI).
const agreementWord = d => { const n = Math.abs(num(d) ?? 99); return n === 99 ? '' : n <= 1 ? 'Close agreement' : n <= 2 ? 'Moderate difference' : 'Significant difference'; };


// ── 3. Feedback text -> HTML ────────────────────────────────────
// The AI feedback is plain text like this:
//     Summary
//     Two sentences.
//
//     Semantic (meaning & coherence)
//     - Strength: ...
//     - To improve: ...
// Section titles become bold headings, "- " lines become bullets, and "Label:" becomes bold.
// Leftover Markdown (**bold**, # headings, "* " bullets) from older records is cleaned up too.
const TITLES = ['Summary', 'Semantic', 'Stylistic', 'Pragmatic', 'Overall rating'];

function feedbackHtml(text) {
  let html = '';
  let bullets = '';
  const endList = () => {
    if (bullets) html += `<ul style="margin:4px 0 10px;padding-left:20px">${bullets}</ul>`;
    bullets = '';
  };
  const boldLabel = s => esc(s).replace(/^([A-Z][A-Za-z ]{2,24}):\s/, '<b>$1:</b> ');

  for (let line of String(text || '-').split('\n')) {
    line = line.replace(/\*\*/g, '').replace(/^#+\s*/, '').replace(/^\*\s+/, '- ').trim();

    if (line.startsWith('- ')) {                       // a bullet
      bullets += `<li style="padding:2px 0">${boldLabel(line.slice(2))}</li>`;
      continue;
    }
    endList();
    if (!line) continue;                               // a blank line
    const isTitle = TITLES.some(t => line.startsWith(t)) && !/[:.]/.test(line);
    html += isTitle
      ? `<div style="font:600 14px/1.4 ${SANS};color:${C.plum};padding:12px 0 2px">${esc(line)}</div>`
      : `<div style="padding:2px 0 6px">${boldLabel(line)}</div>`;
  }
  endList();
  return html;
}


// ── 4. Small HTML pieces (each one is a table row, or a bit of one) ──
const table = (inner, style = '') =>
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;${style}">${inner}</table>`;

// A section title, and a block of text under it.
const heading = text =>
  `<tr><td style="padding:26px 32px 6px;font:600 15px/1.3 ${SANS};color:${C.ink}">${esc(text)}</td></tr>`;
const textBlock = html =>
  `<tr><td style="padding:0 32px;font:400 14.5px/1.65 ${SANS};color:${C.body}">${html}</td></tr>`;
const plainText = text => textBlock(esc(text || '-').replace(/\n/g, '<br>'));
const feedbackBlock = text => textBlock(feedbackHtml(text));

// A coloured score bar (0 to 10) made of two table cells.
const bar = (value, color) => {
  const pct = Math.max(0, Math.min(100, Math.round((num(value) || 0) * 10)));
  const filled = pct ? `<td width="${pct}%" height="8" bgcolor="${color}" style="font-size:0;line-height:0">&nbsp;</td>` : '';
  const empty = pct < 100 ? `<td height="8" bgcolor="${C.sunk}" style="font-size:0;line-height:0">&nbsp;</td>` : '';
  return table(`<tr>${filled}${empty}</tr>`);
};

// A highlighted warning with a coloured stripe on the left.
const notice = (html, color) =>
  `<tr><td style="padding:16px 32px 0">` + table(`<tr>
     <td width="3" bgcolor="${color}" style="font-size:0">&nbsp;</td>
     <td style="padding:10px 14px;background:${C.sand};font:400 13.5px/1.55 ${SANS};color:${C.body}">${html}</td>
   </tr>`) + `</td></tr>`;

// One box in the row of scores (label, big number, small caption).
const scoreCell = (label, value, caption, color, isLast) => `
  <td align="center" valign="top" style="padding:16px 8px;${isLast ? '' : `border-right:1px solid ${C.line};`}">
    <div style="font:400 12.5px/1.3 ${SANS};color:${C.muted}">${esc(label)}</div>
    <div style="font:500 30px/1.25 ${MONO};color:${color};padding-top:4px">${value}</div>
    <div style="font:400 12.5px/1.3 ${SANS};color:${C.muted};padding-top:2px">${esc(caption)}</div>
  </td>`;

// "Domain  General" and "Topic  ..." lines under the greeting.
const detailRow = (name, value) => `<tr>
  <td width="70" valign="top" style="padding:3px 0;font:400 13px/1.5 ${SANS};color:${C.muted}">${name}</td>
  <td style="padding:3px 0;font:500 14px/1.5 ${SANS};color:${C.ink}">${esc(value || '-')}</td></tr>`;

// A bordered panel around the scores.
const scorePanel = inner =>
  `<tr><td style="padding:20px 32px 0">${table(`<tr>${inner}</tr>`, `border:1px solid ${C.line}`)}</td></tr>`;


// ── 5. Build one email for each item n8n receives ───────────────
const out = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;            // the data sent by the Flask backend
  const isComparison = b.type === 'comparison';
  const firstName = String(b.name || '').trim().split(/\s+/)[0] || 'there';

  // Names of the attached PDFs, for the "Attached:" line ("comparison_report.pdf" -> "Comparison report").
  const files = (b.attachments || [])
    .map(a => String(a.filename || '').replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim())
    .filter(Boolean)
    .map(name => name.charAt(0).toUpperCase() + name.slice(1).toLowerCase().replace(/\bai\b/g, 'AI'));

  // Warnings (only when there is something to warn about).
  let warnings = '';
  if (b.irrelevant) warnings += notice('<b>Off-topic essay.</b> The essay did not address the assigned topic, so the AI scored it 0.', C.bad);
  if (b.ai_generated?.detected) warnings += notice(`<b>AI-generated text flagged.</b> The detector estimates a ${esc(b.ai_generated.confidence)}% likelihood that this text was AI-generated.`, C.mid);

  // The parts that differ between the two kinds of email.
  let subject, preview, intro, scores, feedback;

  if (isComparison) {
    const diff = num(b.difference);
    subject = `Your essay review is ready: AI ${fmt(b.ai_marks)}/10, admin ${fmt(b.admin_marks)}/10`;
    preview = 'The admin has scored your essay. Reports are attached.';
    intro = 'An admin has reviewed your essay. ' + (files.length ? `The ${files.length > 1 ? 'reports are' : 'report is'} attached as PDF.` : '');
    scores = scorePanel(
      scoreCell('AI score', esc(fmt(b.ai_marks)), scoreWord(b.ai_marks), C.peachInk, false) +
      scoreCell('Admin score', esc(fmt(b.admin_marks)), scoreWord(b.admin_marks), C.plum, false) +
      scoreCell('Difference', diff === null ? '-' : (diff > 0 ? '+' : '') + esc(fmt(diff)), agreementWord(diff), C.ink, true));
    feedback = heading('AI feedback') + feedbackBlock(b.overall_feedback) +
               heading('Admin feedback') + plainText(b.admin_feedback);
  } else {
    const dimensions = [['Semantic', b.semantic?.score], ['Stylistic', b.stylistic?.score], ['Pragmatic', b.pragmatic?.score]];
    const barRows = dimensions.map(([name, score]) => `<tr>
        <td width="90" style="padding:7px 0;font:500 14px/1.3 ${SANS};color:${C.ink}">${name}</td>
        <td style="padding:7px 0">${bar(score, C.plum)}</td>
        <td width="48" align="right" style="padding:7px 0;font:500 13.5px/1.3 ${MONO};color:${scoreColor(score)}">${esc(fmt(score))}</td>
      </tr>`).join('');
    subject = `Your essay result: ${fmt(b.avg_score)}/10`;
    preview = 'Your AI evaluation is ready.';
    intro = 'Your essay has been evaluated by the AI. ' + (files.length ? 'The full report is attached as PDF.' : '');
    scores = scorePanel(`
      <td width="150" align="center" valign="middle" style="padding:18px 8px;border-right:1px solid ${C.line}">
        <div style="font:400 12.5px/1.3 ${SANS};color:${C.muted}">Overall score</div>
        <div style="font:500 36px/1.2 ${MONO};color:${scoreColor(b.avg_score)};padding-top:4px">${esc(fmt(b.avg_score))}</div>
        <div style="font:400 12.5px/1.3 ${SANS};color:${C.muted}">out of 10 (${esc(scoreWord(b.avg_score))})</div>
      </td>
      <td style="padding:12px 18px">${table(barRows)}</td>`);
    feedback = heading('Overall feedback') + feedbackBlock(b.overall_feedback);
  }

  // The whole email page: header, greeting, details, scores, warnings, feedback, footer.
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:${C.sand}">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:${C.sand}">${esc(preview)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.sand}"><tr><td align="center" style="padding:28px 12px">

  <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;border-collapse:collapse;background:#ffffff;border:1px solid ${C.line}">
    <tr><td style="background:${C.ink};padding:20px 32px;border-bottom:3px solid ${C.peach}">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td style="font:600 14px/1 ${SANS};letter-spacing:2.5px;color:${C.sand}">SCUBA ANALYZER</td>
        <td align="right" style="font:400 13px/1 ${SANS};color:#C6B4A8">${isComparison ? 'Essay review' : 'Essay result'}</td>
      </tr></table>
    </td></tr>
    <tr><td style="padding:30px 32px 0;font:400 15px/1.6 ${SANS};color:${C.body}">Hello ${esc(firstName)},<br><br>${esc(intro.trim())}</td></tr>
    <tr><td style="padding:18px 32px 0"><table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse">${detailRow('Domain', b.domain)}${detailRow('Topic', b.topic)}</table></td></tr>
    ${scores}
    ${warnings}
    ${feedback}
    ${files.length ? `<tr><td style="padding:24px 32px 0;font:400 13px/1.6 ${SANS};color:${C.muted}">Attached: ${files.map(esc).join('; ')}.</td></tr>` : ''}
    <tr><td style="padding:28px 32px 30px;font:400 13px/1.6 ${SANS};color:${C.muted}">Questions about your score? Contact your administrator.</td></tr>
  </table>

  <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px"><tr>
    <td align="center" style="padding:16px 8px;font:400 12px/1.6 ${SANS};color:${C.muted}">Sent by Scuba Analyzer because an essay was submitted with this email address.</td>
  </tr></table>

</td></tr></table>
</body></html>`;

  // ── 6. Attach the PDFs ──
  // The backend sends each PDF as base64 text; n8n needs real files ("binary data").
  const binary = {};
  let index = 0;
  for (const attachment of (b.attachments || [])) {
    binary[`file${index}`] = await this.helpers.prepareBinaryData(
      Buffer.from(attachment.base64, 'base64'), attachment.filename || `report${index}.pdf`, 'application/pdf');
    index++;
  }

  out.push({ json: { to: b.to, subject, html, attachmentFields: Object.keys(binary).join(',') }, binary });
}

return out;
